(: Branch 1: Regex constructor — uses @Identifier on PrimaryExpression; matchesSig has column-range bug on multi-line PUEs :)
//FunctionDeclaration//PostfixUnaryExpression[PrimaryExpression[@Identifier='Regex']
    (: not called on fun parameter :)
    and not(.//CallSuffix//PrimaryExpression//T-Identifier[
        @Text = ancestor::FunctionDeclaration//FunctionValueParameter//Parameter/@Identifier])
    (: not called on 'dynamic' function call — from outer PUE: chain-call + Regex-call + inner-call = 3 levels :)
    and not(ancestor::PostfixUnaryExpression/PostfixUnarySuffix/CallSuffix//CallSuffix//CallSuffix)
    (: not if based on local variable initialized by fun parameter :)
    and not(ancestor::CallSuffix//PostfixUnaryExpression/PrimaryExpression[@Identifier =
        ancestor::FunctionBody//PropertyDeclaration/VariableDeclaration/@Identifier])
    (: not param in String template in fun parameter :)
    and not(.//CallSuffix/ValueArguments/ValueArgument//LineStringContent/T-LineStrRef[
       @Text = ancestor::FunctionDeclaration//Parameter/SimpleIdentifier/T-Identifier/concat('$', @Text)])
    (: not param in String template of class var field :)
    and not(.//CallSuffix/ValueArguments/ValueArgument//LineStringContent/T-LineStrRef[
       @Text = ancestor::ClassDeclaration//PropertyDeclaration[T-VAR]//SimpleIdentifier/T-Identifier/concat('$', @Text)])
    (: not param in String concatenation of class var field :)
    and not(.//CallSuffix/ValueArguments/ValueArgument[//LineStringLiteral]//AdditiveExpression/MultiplicativeExpression//SimpleIdentifier/T-Identifier[
       @Text = ancestor::ClassDeclaration//PropertyDeclaration[T-VAR]//VariableDeclaration/@Identifier])
]

|

